const phone = ($input.first().json.phone || '').replace(/^\+/, '');
const last10 = phone.slice(-10);
return [{ json: {
  phone,
  q_full: JSON.stringify({ celular: { lk: phone } }),
  q_sin9: JSON.stringify({ celular: { lk: '+54' + last10 } }),
  q_solo_local: JSON.stringify({ celular: { lk: last10 } }),
  trigger: $input.first().json
}}];

// Procesar resultado, retornar paciente o flag retry
const lookupRaw = $input.first().json;
const trigger = $('Step 1.0: Prep Query').first().json.trigger;
const __err1 = Array.isArray(lookupRaw) ? (lookupRaw[0] && lookupRaw[0].error) : (lookupRaw && lookupRaw.error);
if (__err1) { return [{ json: { ok:false, step:'error_tecnico', tech_error:true, raw:lookupRaw, trigger } }]; }
let data = [];
if (Array.isArray(lookupRaw)) data = lookupRaw[0]?.data || [];
else data = lookupRaw?.data || lookupRaw?.['0']?.data || [];

if (data.length > 0) {
  // FIX 2026-06-04: si multiple_fichas, intentar match por contexto del chat history
  let pacienteResuelto = data[0];
  let resolvedBy = null;
  if (data.length > 1) {
    try {
      const chMem = $('Step 0a: Read Chat Memory').all() || [];
      const isMultiList = (txt) => /tengo\s+registrad[ao]s?\s+a\b|con\s+este\s+n[u\u00fa]mero\s+(figura|tengo|tiene)/i.test(txt);
      const chatHistoryText = chMem.map(it => {
        const m = it.json && it.json.message ? it.json.message : {};
        const c = (m.content || '').toString();
        if (isMultiList(c) || /\u00c1UREA\s+ODONTOLOG|\[NOTA INTERNA|Le recordamos su turno|^-\s*Paciente:/im.test(c)) return ''; // ROUND 14: fragmentos sueltos de recordatorio
        return c;
      }).filter(Boolean).join('\n').toLowerCase();
      const msgPaciente = (trigger && trigger.text || '').toLowerCase();
      const searchPool = msgPaciente + '\n' + chatHistoryText;
      const STOP_TOKENS = new Set(['test','prueba','paciente','el','la','los','las','de','del','dr','dra','sr','sra']);
      const tokenizar = (s) => (s || '').toLowerCase()
        .replace(/[^a-z\u00e1\u00e9\u00ed\u00f3\u00fa\u00f10-9\s]/gi, ' ')
        .split(/\s+/)
        .filter(t => t.length >= 3 && !STOP_TOKENS.has(t));
      const matchPorTokens = (texto) => { // ROUND 14: token completo (Set), no substring cruda
        const poolTokens = new Set(tokenizar(texto));
        return data.filter(p => {
          const tokens = [...tokenizar(p.nombre || ''), ...tokenizar(p.apellidos || p.apellido || '')];
          return tokens.length > 0 && tokens.some(t => poolTokens.has(t));
        });
      };
      let matched = matchPorTokens(msgPaciente); // 1ra pasada: solo lo que dijo AHORA
      if (matched.length !== 1) matched = matchPorTokens(searchPool); // fallback: pool completo
      if (matched.length === 1) {
        pacienteResuelto = matched[0];
        resolvedBy = 'context_match';
      }
    } catch(e) { /* fallback a data[0] */ }
  }
  return [{ json: {
    ok: true,
    step: 'paciente_encontrado',
    paciente: pacienteResuelto,
    multiple_fichas: data.length > 1 && !resolvedBy,  // si resolved, ya no es ambiguo
    multi_fichas_resolved_by: resolvedBy,
    pacientes_all: data,
    variant_used: 'celular_completo',
    trigger
  }}];
}

return [{ json: {
  ok: false,
  step: 'paciente_no_encontrado',
  raw: lookupRaw,
  trigger
}}];

const turnosRaw = $input.first().json;
const paciente = $('Step 1b: Procesar resultado').first().json.paciente;
const trigger = $('Step 1b: Procesar resultado').first().json.trigger;
const __err2 = Array.isArray(turnosRaw) ? (turnosRaw[0] && turnosRaw[0].error) : (turnosRaw && turnosRaw.error);
const __tech2b = !!__err2 || ($('Step 1b: Procesar resultado').first().json.tech_error === true);

let turnos = [];
if (Array.isArray(turnosRaw)) turnos = turnosRaw[0]?.data || [];
else turnos = turnosRaw?.data || [];

const hoy = new Date();
hoy.setHours(0,0,0,0);
const proximos = turnos
  .filter(t => t.id_estado !== 1 && t.id_estado !== 14)
  .filter(t => {
    if (!t.fecha) return false;
    const f = new Date(t.fecha + 'T00:00:00');
    return f >= hoy;
  })
  .map(t => ({
    id: t.id,
    fecha: t.fecha,
    hora_inicio: t.hora_inicio,
    hora_fin: t.hora_fin,
    id_estado: t.id_estado,
    id_dentista: t.id_dentista,
    comentario: t.comentario || '',
    nombre_estado: t.nombre_estado || ''
  }))
  .sort((a, b) => String(a.fecha + ' ' + (a.hora_inicio || '')).localeCompare(String(b.fecha + ' ' + (b.hora_inicio || ''))));

return [{ json: {
  tech_error: __tech2b,
  ok: proximos.length > 0,
  paciente,
  trigger,
  turnos_proximos: proximos,
  count: proximos.length
}}];

const llmResp = $input.first().json;
const prev = $('Step 2b: Filtrar Turnos Proximos').first().json;

let parsed = { accion: 'ambiguo', fecha_objetivo: null, hora_objetivo: null, franja: null, hora_minima: null, insiste_horario: false, fecha_actual_mencionada: null, razon: 'sin parse' };
try {
  const content = llmResp?.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed.razon = 'json parse fail: ' + String(e?.message || e);
}

return [{ json: {
  paciente: prev.paciente,
  trigger: prev.trigger,
  turnos_proximos: prev.turnos_proximos,
  count: prev.count,
  intent: parsed,
  step: 'intent_extracted'
}}];

const prev = $input.first().json;
const text = prev.trigger?.text || '';
const state = prev.trigger?.multi_turn_state || 'conversacion_nueva';
const lastBot = prev.trigger?.last_bot_msg || '';
const convHistory = prev.trigger?.conversation_history || '';
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Jujuy' }).format(new Date()); // ROUND 14: bug UTC (21:00-23:59 ARG calculaba "hoy" mal)

const conversationContext = convHistory
  ? "HISTORIAL DE CONVERSACION RECIENTE (mas reciente abajo):\n" + convHistory + "\n\nEl mensaje del paciente que tenes que parsear AHORA es: \"" + text + "\". Razona con el historial: si el bot acaba de preguntar algo y el paciente responde con palabra corta (si, no, ese, eso, dale), conecta los puntos. Ejemplos: bot dice 'Era ese el turno del [fecha]?' + paciente 'si' -> accion=cancelar + fecha_actual_mencionada=fecha. Bot ofrece slots + paciente 'el de las X' -> accion=reprogramar. Bot 'que dia preferis?' + paciente 'por la tarde' -> franja='tarde' + accion=reprogramar. Bot 'que hora?' + paciente 'despues de las 17hs' -> franja='tarde' + hora_minima=17 + accion=reprogramar. Si el bot acaba de ofrecer alternativas por la mañana y el paciente insiste 'solo puedo a las 17' o 'solo por la tarde' -> franja='tarde' + hora_minima=17 + insiste_horario=true + accion=reprogramar. No respondas en base solo al mensaje del paciente: tene en cuenta el flujo completo de la conversacion."
  : "";

const body = {
  model: 'gpt-5',
  messages: [
    { role: 'system', content: "Sos un parser de mensajes de pacientes sobre sus turnos dentales. Hoy es " + today + ". " + conversationContext + " Tu tarea: extraer del mensaje del paciente (en contexto del historial conversacional) la INTENT y campos relevantes. Responde SOLO con JSON valido, formato exacto: {\"accion\":\"cancelar\"|\"reprogramar\"|\"consultar_info\"|\"ambiguo\",\"fecha_objetivo\":\"YYYY-MM-DD\"|null,\"hora_objetivo\":\"HH:MM\"|null,\"franja\":\"tarde\"|\"manana\"|null,\"hora_minima\":17|null,\"insiste_horario\":true|false,\"fecha_actual_mencionada\":\"YYYY-MM-DD\"|null,\"info_solicitada\":\"cuando\"|\"donde\"|\"tratamiento\"|\"verificar_fecha\"|null,\"razon\":\"texto breve\"}. Reglas: (1) Si paciente dice 'cancelar el [fecha]' = cancelar + fecha_actual_mencionada. (2) Si dice 'reprogramar' o 'pasarlo a otro dia' o 'tengo clases' = reprogramar. (3) Si paciente indica franja ('tarde', 'mañana') o hora ('despues de las 17hs', 'solo a las 17'), extrae franja ('tarde'|'manana') y hora_minima (ej 17 para 17hs). (4) Si el bot le ofrecio mañanas y paciente dice 'solo puedo por la tarde/17hs', setea insiste_horario=true. (5) CONSULTA DE INFO: si paciente PREGUNTA sin querer accion -> accion='consultar_info'. NO uses con_quien. Calcula año: si fecha mencionada ya paso este año usa siguiente año." },
    { role: 'user', content: 'Mensaje del paciente: ' + text }
  ],
  max_completion_tokens: 800,
  reasoning_effort: 'minimal',
  response_format: { type: 'json_object' }
};
return [{ json: { ...prev, openai_body: JSON.stringify(body) } }];

// Identificar turno objetivo + decidir next step
const prev = $input.first().json;
const intent = prev.intent || {};
const turnos = prev.turnos_proximos || [];

// FIX 2026-07-01: error tecnico en lookup/ver-turnos -> escalar (no mentir "no tenes turnos").
let __techErr = false;
try { if ($('Step 1b: Procesar resultado').first().json.tech_error === true) __techErr = true; } catch(e){}
try { if ($('Step 2b: Filtrar Turnos Proximos').first().json.tech_error === true) __techErr = true; } catch(e){}
if (__techErr) {
  return [{ json: { ...prev, decision: {
    siguiente_paso: 'escalar', razon: 'error_tecnico_dentalink',
    canned: 'Disculpe, tuve un inconveniente tecnico para acceder a la agenda en este momento. Le paso a la secretaria, que la coordina en su horario de atencion (Lun y Mie 15 a 20 hs / Mar, Jue y Vie 8 a 13 hs).'
  } }}];
}

// === Anti-loop / anti-frustracion (27/05) ===
// Si el bot ya repitio la canned 2+ veces o el paciente esta frustrado,
// cortar el loop y escalar a humano directo. Step 0b setea los flags.
const loopNoTurnos = prev.trigger?.loop_no_turnos === true;
const isFrustrated = prev.trigger?.is_frustrated === true;
if (loopNoTurnos || isFrustrated) {
  return [{ json: {
    ...prev,
    decision: {
      siguiente_paso: 'escalar',
      razon: loopNoTurnos && isFrustrated ? 'loop_canned_y_frustracion'
           : loopNoTurnos ? 'loop_canned_repetida_2x'
           : 'paciente_pide_ayuda_explicita',
      canned: 'Le paso a la secretaria para que pueda ayudarle con esto.'
    }
  }}];
}

// === Fix B 2026-06-03: celular compartido por varias fichas (familia) -> PREGUNTAR (o usar contexto), NO escalar ===
const step1b = $('Step 1b: Procesar resultado').first().json;
const multipleFichas = step1b.multiple_fichas === true;
if (multipleFichas) {
  const pacientesAll = step1b.pacientes_all || [];
  // FIX 2026-07-01: tras resolver ficha (DNI/contexto) enganchar el turno para NO dead-endear.
  // Conservador: solo si los turnos ya fetcheados pertenecen a la ficha resuelta
  // (turnos_proximos se traen para pacientesAll[0]); exige match de fecha si el paciente la menciono.
  const __pickTurno = (rid) => {
    try {
      if (!(pacientesAll[0] && pacientesAll[0].id === rid)) return null;
      const tp = prev.turnos_proximos || [];
      if (!tp.length) return null;
      const fm = (intent && intent.fecha_actual_mencionada) || null;
      if (fm) return tp.find(t => t.fecha === fm) || null;
      return tp.length === 1 ? tp[0] : null;
    } catch (e) { return null; }
  };
  // Construir texto a buscar: mensaje actual del paciente + chat_history reciente
  const msgPaciente = (prev.trigger && prev.trigger.text) || '';
  let chatHistoryText = '';
  try {
    const chMem = $('Step 0a: Read Chat Memory').all() || [];
    // FIX 2026-06-04: excluir mensajes del bot listando multiples pacientes
    const isMultiList = (txt) => /tengo\s+registrad[ao]s?\s+a\b|con\s+este\s+n[u\u00fa]mero\s+(figura|tengo|tiene)/i.test(txt);
    chatHistoryText = chMem.map(it => {
      const m = it.json && it.json.message ? it.json.message : {};
      const c = (m.content || '').toString();
      if (isMultiList(c)) return '';
      return c;
    }).filter(Boolean).join('\n').toLowerCase();
  } catch(e) { chatHistoryText = ''; }
  const searchPool = (msgPaciente + '\n' + chatHistoryText).toLowerCase();

  // DNI match (pedido Dra 2026-06-17): si el paciente paso un DNI, matchear exacto contra rut de las fichas (sin puntos).
  const dniRaw = (msgPaciente.replace(/[.\-\s]/g, '').match(/\d{7,9}/) || [])[0];
  if (dniRaw) {
    const byDni = pacientesAll.filter(p => String(p.rut || '').replace(/\D/g, '') === dniRaw);
    if (byDni.length === 1) {
      return [{ json: { ...prev, paciente_resuelto: byDni[0], paciente: byDni[0], turno_objetivo: __pickTurno(byDni[0].id), multi_fichas_resolved_by: 'dni_match', decision: __pickTurno(byDni[0].id) ? null : { siguiente_paso: 'escalar', razon: 'reprograma: identificado por DNI pero no se pudo enganchar el turno (coordinar a mano)', canned: 'Le paso a la secretaria para coordinar su reprogramacion.' } } }];
    }
  }

  // FIX 2026-06-04 (token match): el matcheo anterior buscaba 'Test - Lucas' literal,
  // pero memoria dice 'Lucas Silva' (sin 'Test -'). Ahora tokenizamos y matchamos
  // si AL MENOS UN token relevante (>=3 chars, alfanumerico) coincide.
  const STOP_TOKENS = new Set(['test','prueba','paciente','el','la','los','las','de','del','dr','dra','sr','sra']);
  const tokenizar = (s) => (s || '').toLowerCase()
    .replace(/[^a-záéíóúñ0-9\s]/gi, ' ')
    .split(/\s+/)
    .filter(t => t.length >= 3 && !STOP_TOKENS.has(t));
  const matched = pacientesAll.filter(p => {
    const nombre = (p.nombre || '').toLowerCase().trim();
    const apellido = (p.apellido || '').toLowerCase().trim();
    if (!nombre && !apellido) return false;
    const tokens = [...tokenizar(nombre), ...tokenizar(apellido)];
    if (tokens.length === 0) return false;
    // Match si AL MENOS UN token aparece en searchPool
    return tokens.some(t => searchPool.includes(t));
  });

  // DEBUG temporal
  const DEBUG = { msgPaciente, chatHistoryText: chatHistoryText.slice(0, 500), searchPool: searchPool.slice(0, 500), pacientesAll_count: pacientesAll.length, matched_count: matched.length, matched_ids: matched.map(p=>p.id), pacientesAll_tokens: pacientesAll.map(p => ({id: p.id, nombre: p.nombre, tokens: [...tokenizar(p.nombre || ''), ...tokenizar(p.apellido || '')]})) };
  if (matched.length === 1) {
    return [{ json: {
      ...prev,
      paciente_resuelto: matched[0],
      paciente: matched[0],
      turno_objetivo: __pickTurno(matched[0].id),
      multi_fichas_resolved_by: 'context_match',
      decision: __pickTurno(matched[0].id) ? null : { siguiente_paso: 'escalar', razon: 'reprograma: identificado por contexto pero no se pudo enganchar el turno (coordinar a mano)', canned: 'Le paso a la secretaria para coordinar su reprogramacion.' },
      _debug_match: DEBUG
    }}];
  }
  // FALLBACK con debug
  prev._debug_match = DEBUG;

  // No hay match unico -> preguntar listando los nombres
  const lista = pacientesAll.slice(0, 6).map(p => {
    const n = (p.nombre || '').trim();
    const a = (p.apellido || '').trim();
    return (n + ' ' + a).trim() || '(sin nombre)';
  });
  return [{ json: {
    ...prev,
    decision: {
      siguiente_paso: 'preguntar_nombre_paciente',
      razon: 'multiple_fichas_pedir_clarificacion',
      canned: 'Con este numero tengo registradas a ' + lista.slice(0,-1).join(', ') + (lista.length > 1 ? ' y ' + lista[lista.length-1] : lista[0]) + '. ¿Me pasás el DNI del paciente para identificarlo? (o su nombre y apellido)'
    }
  }}];
}

function fechaNatural(yyyyMmDd) {
  if (!yyyyMmDd) return '';
  const dias = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
  const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  const d = new Date(yyyyMmDd + 'T00:00:00');
  if (isNaN(d.getTime())) return yyyyMmDd;
  return dias[d.getDay()] + ' ' + d.getDate() + ' de ' + meses[d.getMonth()];
}
function horaNatural(hhmmss) {
  if (!hhmmss) return '';
  const m = String(hhmmss).match(/^(\d{1,2}):(\d{2})/);
  if (!m) return hhmmss;
  const h = parseInt(m[1], 10);
  const mm = m[2];
  const sufijo = h < 12 ? 'de la mañana' : (h < 19 ? 'de la tarde' : 'de la noche');
  return h + (mm !== '00' ? ':' + mm : '') + ' ' + sufijo;
}

// NUEVO: si bot pregunto clarificacion ('era ese?'), y paciente dice si/ese/eso -> confirmar
const stateClar = prev.trigger?.multi_turn_state === 'esperando_confirmacion_clarificacion';
const lowerText = (prev.trigger?.text || '').toLowerCase().trim();
const isAffirm = /^(si+|sí+|sip+|claro|exacto|correcto|ese|ese mismo|ese si|ese sí|eso|eso es|eso mismo|asi es|así es|tal cual) /.test(lowerText);
const isNegative = /^(no+|nop+|nono|no era|ese no|no ese) /.test(lowerText);
if (stateClar && turnos.length >= 1) {
  if (isAffirm) {
    return [{ json: {
      ...prev,
      turno_objetivo: turnos[0],
      decision: { siguiente_paso: 'confirmar_cancelacion', razon: 'clarificacion_confirmada_paciente_acepto' }
    }}];
  }
  if (isNegative) {
    return [{ json: {
      ...prev,
      decision: {
        siguiente_paso: 'responder_info',
        razon: 'clarificacion_rechazada',
        canned: 'Entendido, ese no era. Si tenes otro turno o queres coordinarlo decime y lo vemos.'
      }
    }}];
  }
}

// NUEVO: consultar_info — responder con info sin escalar
if (intent.accion === 'consultar_info') {
  if (turnos.length === 0) {
    return [{ json: {
      ...prev,
      decision: {
        siguiente_paso: 'responder_info',
        razon: 'consulta_info_sin_turnos_activos',
        canned: 'Por el momento no tenes turnos activos a tu nombre. Si queres agendar uno avisame y te lo coordino.'
      }
    }}];
  }

  const info = intent.info_solicitada || 'cuando';

  // Caso verificar_fecha: paciente pregunta "tengo turno [tal dia]?"
  if (info === 'verificar_fecha' && intent.fecha_actual_mencionada) {
    const match = turnos.find(t => t.fecha === intent.fecha_actual_mencionada);
    let canned;
    if (match) {
      canned = 'Si, tenes turno el ' + fechaNatural(match.fecha) + ' a las ' + horaNatural(match.hora_inicio) + '.';
    } else {
      const proxLista = turnos.slice(0, 3).map(t => fechaNatural(t.fecha) + ' a las ' + horaNatural(t.hora_inicio)).join(' / ');
      canned = 'No, no tenes turno el ' + fechaNatural(intent.fecha_actual_mencionada) + '. Tu proximo turno es: ' + proxLista + '.';
    }
    return [{ json: { ...prev, decision: { siguiente_paso: 'responder_info', razon: 'verificar_fecha', canned } } }];
  }

  // Caso cuando / con_quien / donde / tratamiento — todos con turno_objetivo (1+)
  const turnosStr = turnos.length === 1
    ? fechaNatural(turnos[0].fecha) + ' a las ' + horaNatural(turnos[0].hora_inicio)
    : turnos.slice(0, 3).map(t => fechaNatural(t.fecha) + ' a las ' + horaNatural(t.hora_inicio)).join(' / ');

  let canned;
  if (info === 'cuando') {
    canned = turnos.length === 1
      ? 'Tu proximo turno es el ' + turnosStr + '.'
      : 'Tenes ' + turnos.length + ' turnos proximos: ' + turnosStr + '.';
  } else if (info === 'donde') {
    canned = 'Tu turno es presencial en Balcarce 37, 2do piso, San Salvador de Jujuy. Fecha: ' + turnosStr + '.';
  } else if (info === 'tratamiento') {
    // No tenemos el campo de tratamiento por turno desde Dentalink en este flow.
    canned = 'Para ver el detalle del tratamiento de tu proximo turno (' + turnosStr + ') te paso a la secretaria que tiene la ficha clinica.';
  } else {
    // Fallback consulta_info generica
    canned = turnos.length === 1
      ? 'Tu proximo turno es el ' + turnosStr + '.'
      : 'Tenes ' + turnos.length + ' turnos proximos: ' + turnosStr + '.';
  }
  return [{ json: { ...prev, decision: { siguiente_paso: 'responder_info', razon: 'consulta_info_turno', canned } } }];
}

// Caso 1: NO HAY turnos proximos
if (turnos.length === 0) {
  if (intent.accion === 'cancelar' || intent.accion === 'reprogramar') {
    return [{ json: {
      ...prev,
      decision: {
        siguiente_paso: 'responder_info',
        razon: 'paciente_sin_turnos_para_accion',
        canned: 'No te encuentro turnos activos en este momento. Si queres coordinar uno nuevo avisame y te lo paso a la secretaria.'
      }
    }}];
  }
  return [{ json: {
    ...prev,
    decision: {
      siguiente_paso: 'responder_info',
      razon: 'consulta_turnos_sin_turnos_activos',
      canned: 'Por el momento no tenes turnos activos a tu nombre. Si queres agendar uno avisame y te lo coordino.'
    }
  }}];
}

// Si paciente menciono fecha actual, verificar si matchea con algun turno
const fechaMencionada = intent.fecha_actual_mencionada;
const match = fechaMencionada ? turnos.find(t => t.fecha === fechaMencionada) : null;

if (fechaMencionada && !match) {
  return [{ json: {
    ...prev,
    decision: {
      siguiente_paso: 'preguntar_cual_turno',
      razon: 'fecha_mencionada_no_matchea_ningun_turno',
      turnos_para_ofrecer: turnos.slice(0, 5).map(t => ({ id: t.id, fecha: t.fecha, hora: t.hora_inicio }))
    }
  }}];
}

if (match) {
  return [{ json: {
    ...prev,
    turno_objetivo: match,
    decision: {
      siguiente_paso: intent.accion === 'cancelar' ? 'confirmar_cancelacion' :
                      (intent.accion === 'reprogramar' ?
                        (intent.fecha_objetivo ? 'buscar_horarios_objetivo' : 'pedir_fecha_objetivo')
                        : 'preguntar_intent'),
      razon: 'turno_matched_por_fecha_mencionada'
    }
  }}];
}

// Caso 2: UN solo turno proximo
if (turnos.length === 1) {
  const turno = turnos[0];
  if (intent.accion === 'cancelar') {
    return [{ json: {
      ...prev,
      turno_objetivo: turno,
      decision: { siguiente_paso: 'confirmar_cancelacion', razon: 'turno_unico_proximo_a_cancelar' }
    }}];
  }
  if (intent.accion === 'reprogramar') {
