const repeticionesBot = botMsgsRecientes.filter(h => fraseLoop.test(h.content)).length;
const loop_no_turnos = repeticionesBot >= 2;

const fraseFrustracion = /(^|\s)(repito|ya te dije|ya dije|reitero|como te dije|otra vez te digo|no entiendo|no me entend[eé]s|insisto|cuantas veces)([\s,.!?]|$)/i;
const userText = String(trigger.text || '').toLowerCase();
const is_frustrated = fraseFrustracion.test(userText);

// === LOTE DE TURNOS YA OFRECIDO (2026-09-07, pedido de la Dra. Raquel) ===
// El bot ahora ofrece un BLOQUE ("Tenemos los proximos turnos disponibles:" + seccion mañana + seccion
// tarde). SIN ESTO el paciente que rechaza el bloque recibe EXACTAMENTE el mismo bloque de nuevo, para
// siempre: "Step 5" volvia a buscar desde HOY porque nadie se acordaba de que ya se le habia ofrecido un
// lote (esa es la captura #2 que mando la Dra. el 07/09). Aca se saca del ULTIMO mensaje del bot:
//   (a) el bloque entero, para poder señalarle SOLO la franja que pide sin volver a buscar agenda,
//   (b) desde cuando pedir el lote SIGUIENTE,
//   (c) cuantos bloques se le ofrecieron ya, para escalar en vez de tirarle un tercero.
const MESES_BLOQUE = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',
                      'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const HOY_JUJUY = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Jujuy' }).format(new Date());
const RE_BLOQUE = /turnos disponibles:/i;
const oferta_bloque = RE_BLOQUE.test(lastBotMsg || '') ? String(lastBotMsg) : '';

// "* Jueves 24 de septiembre 8:00 , 8:40" -> "2026-09-24". El bloque NO lleva año: se usa el actual y, si
// esa fecha ya paso, el que viene (mismo criterio que el parser de aceptacion de "Step 3.5a").
function isoDeLineaBloque(linea) {
  const m = /^\*\s*[^\d]+?(\d{1,2})\s+de\s+([a-zA-Zá-úÁ-Úñ]+)/.exec(String(linea).trim());
  if (!m) return '';
  const mes = MESES_BLOQUE.indexOf(m[2].toLowerCase()) + 1;
  if (!mes) return '';
  const mm = String(mes).padStart(2, '0');
  const dd = String(Number(m[1])).padStart(2, '0');
  const anio = Number(HOY_JUJUY.slice(0, 4));
  const cand = anio + '-' + mm + '-' + dd;
  return cand >= HOY_JUJUY ? cand : (anio + 1) + '-' + mm + '-' + dd;
}

// Ultimo dia ofrecido POR SECCION. El siguiente lote arranca al dia siguiente del MINIMO de las dos: la
// tarde siempre cae mas lejos (la Dra. atiende tarde solo lunes y miercoles), asi que arrancar despues del
// ultimo turno de TARDE se saltearia mañanas mas proximas que el paciente nunca vio.
const ultimoPorSeccion = {};
let seccionBloque = '';
for (const raw of oferta_bloque.split('\n')) {
  const l = raw.trim();
  if (/^por la (mañana|manana|tarde)/i.test(l)) { seccionBloque = /tarde/i.test(l) ? 'tarde' : 'manana'; continue; }
  if (!seccionBloque || l.charAt(0) !== '*') continue;
  const iso = isoDeLineaBloque(l);
  if (iso && (!ultimoPorSeccion[seccionBloque] || iso > ultimoPorSeccion[seccionBloque])) ultimoPorSeccion[seccionBloque] = iso;
}
const ultimosBloque = Object.keys(ultimoPorSeccion).map(k => ultimoPorSeccion[k]).sort();
let oferta_siguiente_desde = '';
if (ultimosBloque.length) {
  const pb = ultimosBloque[0].split('-').map(Number);
  oferta_siguiente_desde = new Date(Date.UTC(pb[0], pb[1] - 1, pb[2] + 1)).toISOString().slice(0, 10);
}

// Cuantos bloques se le mandaron en los ultimos 10 mensajes. El marcador esta en la PRIMERA linea del
// bloque, asi que el slice(0, 300) de historyPairs no lo pierde.
const bloques_ofrecidos = historyPairs.filter(h => h.role === 'bot' && RE_BLOQUE.test(h.content)).length;

return [{ json: {
  ...trigger,
  multi_turn_state,
  // 600 y no 300: el bloque de turnos mide ~230 chars y con el "Soy Asiri..." adelante se pasaba de 300.
  // Este campo es lo unico que ve el parser de aceptacion (Step 3.5a) para matchear el turno elegido:
  // truncado en 300 se perdia la seccion "Por la tarde" entera.
  last_bot_msg: (lastBotMsg || '').slice(0, 600),
  oferta_bloque,
  oferta_siguiente_desde,
  bloques_ofrecidos,
  last_user_msg: (lastUserMsg || '').slice(0, 200),
  conversation_history,
  loop_no_turnos,
  is_frustrated
}}];

const prev = $input.first().json;
let trig = prev.trigger;
if (typeof trig === 'string') {
  try { trig = JSON.parse(trig); } catch(e) { trig = {}; }
}
trig = trig || {};
const state = trig.multi_turn_state || prev.multi_turn_state || 'conversacion_nueva';
if (state !== 'oferta_horarios') {
  return [{ json: { ...prev, _skip_acceptance: true } }];
}
const lastBot = trig.last_bot_msg || prev.last_bot_msg || '';
const text = trig.text || prev.text || '';
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Jujuy' }).format(new Date()); // ROUND 14: bug UTC (21:00-23:59 ARG calculaba "hoy" mal)
const sysPrompt = "Sos un parser. El bot dental ofrecio horarios al paciente, y este respondio. Hoy es " + today + ". Determinar si el paciente acepta un slot ofrecido y cual. Responde SOLO JSON valido, formato exacto: {\"accepts\":true|false,\"slot_chosen\":{\"fecha\":\"YYYY-MM-DD\",\"hora_inicio\":\"HH:MM\"}|null,\"razon\":\"breve\"}. Reglas: (1) Si paciente dice si/dale/ok/perfecto sin especificar slot Y solo se ofrecio UN slot, accepts=true con ese slot. (2) Si se ofrecieron varios slots y paciente dice solo si, accepts=false. (3) Si paciente menciona una hora especifica (ej 8, 8:00, 8 de la manana, 15:10) o fecha, matcheala con uno de los slots ofrecidos. (4) Si paciente rechaza, accepts=false slot_chosen=null. (5) Si paciente cambia de tema, accepts=false slot_chosen=null. Para fecha: usa SIEMPRE el año actual (" + today.slice(0,4) + ") o el siguiente si la fecha mencionada ya paso este año. NUNCA uses años anteriores.";
const body = {
  model: 'gpt-5',
  messages: [
    { role: 'system', content: sysPrompt },
    { role: 'user', content: 'Slots ofrecidos por el bot: ' + lastBot + '\n\nRespuesta del paciente: ' + text }
  ],
  max_completion_tokens: 600,
  reasoning_effort: 'minimal',
  response_format: { type: 'json_object' }
};
return [{ json: { ...prev, accept_openai_body: JSON.stringify(body), _skip_acceptance: false } }];

const llmResp = $input.first().json;
const prev = $('Step 3.5a: Prep Acceptance LLM').first().json;

// Si skipeamos LLM (no era oferta_horarios), pasar accepts=null
if (prev._skip_acceptance === true) {
  return [{ json: { ...prev, acceptance_intent: { accepts: null, slot_chosen: null, razon: 'no_aplica' } } }];
}

let parsed = { accepts: false, slot_chosen: null, razon: 'sin parse' };
try {
  const content = llmResp?.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) { parsed.razon = 'parse fail: ' + String(e?.message || e); }

return [{ json: { ...prev, acceptance_intent: parsed } }];

const prev = $input.first().json;
const slot = prev.slot_a_reservar || {};
const paciente = prev.paciente || {};

const body = {
  id_dentista: 1,
  id_sucursal: 1,
  id_sillon: 1,
  id_paciente: paciente.id,
  fecha: slot.fecha,
  // El bloque de turnos escribe las horas SIN cero adelante ("8:00", "8:40") — asi las pidio la Dra. — y el
  // parser de aceptacion (Step 3.5c, un LLM) las copia de ahi. La agenda espera HH:MM: se normaliza aca,
  // que es el ultimo lugar antes del POST de reserva.
  hora_inicio: (function (h) { const m = /^(\d{1,2}):(\d{2})/.exec(String(h || '')); return m ? m[1].padStart(2, '0') + ':' + m[2] : h; })(slot.hora_inicio),
  duracion: 40,
  comentario: 'Reprogramado por bot (sub-WF)'
};

return [{ json: { ...prev, reserva_body: JSON.stringify(body) } }];

const prev = $('Step 6d-prep: Build Reserva Body').first().json;
const reservaResp = $('Step 6d-1: POST Reservar').first().json;
return [{ json: {
  ...prev,
  reserva_status: 'fail',
  reserva_resp: reservaResp,
  mensaje_final: 'No pude reservar el horario que elegiste. Le paso a la secretaria para que lo coordine manualmente.',
  apply_label_humano: true,
  flow: 'reservar_y_cancelar_fail_at_reserve'
}}];

const cancelResp = $input.first().json;
const prev = $('Step 6d-prep: Build Reserva Body').first().json;
const reservaResp = $('Step 6d-1: POST Reservar').first().json;

// reserva OK garantizado (vino por rama TRUE)
const cancelOk = cancelResp?.data?.id_estado === 1 || (Array.isArray(cancelResp) && cancelResp[0]?.data?.id_estado === 1);

let mensaje;
if (cancelOk) {
  mensaje = prev.mensaje_final; // ya viene armado del Step 5
} else {
  // Reservo OK pero no canceló viejo. Doble booking → escalar
  mensaje = 'Te reserve el nuevo turno, pero no logre cancelar el anterior automaticamente. Le paso a la secretaria para que ajuste.';
}

return [{ json: {
  ...prev,
  reserva_ok: true,
  cancel_ok: cancelOk,
  reserva_resp: reservaResp,
  cancel_resp: cancelResp,
  mensaje_final: mensaje,
  apply_label_humano: !cancelOk,
  flow: 'reservar_y_cancelar'
}}];

// Step 8a: Prep INSERT human msg
const out = $('Step 7: Output Final').first().json;
const trigger = $('When called by v6').first().json;
const phone = String(trigger?.phone || '');
const userText = String(trigger?.text || '');
const humanMsg = {
  type: 'human',
  content: userText,
  additional_kwargs: { source: 'wa_inbound' },
  response_metadata: {},
  tool_calls: [],
  invalid_tool_calls: []
};
return [{ json: {
  session_id: phone,
  message_json: JSON.stringify(humanMsg),
  ai_message_json: JSON.stringify({
    type: 'ai',
    content: String(out.mensaje_final || ''),
    additional_kwargs: { source: 'wa_outbound' },
    response_metadata: {},
    tool_calls: [],
    invalid_tool_calls: []
  }),
  // Forward for return
  out
} }];
